insert into public.cards (id, track_id, unit_id, level, roles, type, prompt, media, options, answer, explanation,
  why_it_matters, is_allergen, source_ref, review_note, status, updated_by)
values
  ('food-lunch-dinner-0100', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Our oysters are now No. 3 instead of No. 4. What does that mean for the guest?', null, '["A smaller oyster: the lower the number, the smaller the oyster", "A larger oyster: the lower the number, the bigger the oyster", "A milder oyster from Dibba Bay", "The same size, from a different farm"]'::jsonb, '["A larger oyster: the lower the number, the bigger the oyster"]'::jsonb, 'French oysters are graded by number and the scale runs backwards: the lower the number, the bigger the oyster. Moving from No. 4 to No. 3 means a noticeably larger oyster. They''re Normandy oysters from the farmer Hervé again, instead of Dibba Bay.', 'Guests who know oysters will ask, and "bigger than before" is a good reason to order them.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0101', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How many pieces come in the M/M Fish Taco now?', null, '["3", "2", "1", "4"]'::jsonb, '["2"]'::jsonb, 'From now on the M/M Fish Taco is 2 pieces instead of 3: wheat tortilla, battered cod, pico de gallo, avocado, sriracha and sour cream.', 'Telling the guest the right number avoids disappointment when the plate arrives.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0102', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How many people is the M/M Pork Charcuterie Platter good for?', null, '["4 to 5", "6 or more", "2 to 3", "1"]'::jsonb, '["2 to 3"]'::jsonb, 'A smaller sharing plate, good for 2 to 3 guests: porchetta, Parma ham, mortadella and coppa with olives, Belgian pickles and cornichons, served with pane carasau. It''s (P): every meat on it is pork.', 'Helps you suggest the right amount for the table.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0103', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How many cheeses come on the M/M Cheese Selection?', null, '["6, all from the same farm", "5: soft, creamy, goat, hard and blue", "4: goat, hard, blue and smoked", "3: soft, hard and blue"]'::jsonb, '["5: soft, creamy, goat, hard and blue"]'::jsonb, 'Five cheeses from the affineur "Van Tricht": soft, creamy, goat, hard and blue. The exact cheeses can change, but the variety stays the same. Served with chutney, grapes, crackers and walnuts.', 'You can describe the board with confidence even when the cheeses change.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0104', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What gives the Crispy Calamari its extra crispy coating?', null, '["Cornflour and egg white", "Beer batter", "Flour and semolina flour", "Panko breadcrumbs"]'::jsonb, '["Flour and semolina flour"]'::jsonb, 'Argentinian baby squid coated in flour and semolina flour and fried crispy. Semolina is a rough flour that gives an extra crisp coating. Served with garlic aioli and lemon.', 'Guests often ask what makes it so crisp.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0105', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How many "Van Tricht" cheese croquettes come in a portion?', null, '["6", "5", "7", "9"]'::jsonb, '["7"]'::jsonb, 'Seven small croquettes made with our own cheese blend, including "OG Krystal", an aged gouda. With fried parsley and a whole grain mustard dip.', 'Knowing the count helps you suggest it for the right number of guests.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0106', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How many Pigs in Blankets come in a portion?', null, '["10", "8", "12", "6"]'::jsonb, '["12"]'::jsonb, 'Twelve small pork sausages wrapped in pork bacon and oven cooked, with a whole grain mustard mayo dip. Marked (P).', 'A good sharing number to mention for a group.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0107', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What size are the Glazed Pork Rib Bites?', null, '["3 ribs (100 g), a starter for one", "6 ribs (200 g), a snack to share with drinks", "10 ribs (400 g), for the table", "600 g, a main course"]'::jsonb, '["6 ribs (200 g), a snack to share with drinks"]'::jsonb, 'Six BBQ-glazed pork ribs (200 g), a smaller version of the full rib portion, made to be eaten with the hands alongside a drink. The full M/M Glazed Pork Ribs main is 600 g.', 'Stops a guest ordering the snack expecting a main course, or the other way round.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0108', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What dip comes with the BBQ Chicken Wings?', null, '["Garlic aioli", "Blue cheese dip", "Whole grain mustard mayo", "Sour cream and chive"]'::jsonb, '["Blue cheese dip"]'::jsonb, 'Six homemade wings with our own spice mix, floured, fried and tossed in our homemade BBQ sauce. Served with a blue cheese dip (blue cheese, mayo and sour cream) and celery crudités.', 'Guests who don''t like blue cheese may want to know before ordering.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0109', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'A guest asks if the Padron Peppers are spicy. What do you say?', null, '["Only the seeds are hot, so they''re served deseeded", "No: Padron peppers are a non-spicy green pepper, eaten whole", "They''re medium, like a jalapeño", "Yes, they''re very hot"]'::jsonb, '["No: Padron peppers are a non-spicy green pepper, eaten whole"]'::jsonb, 'Padron peppers are a non-spicy green pepper with a crunchy bite. They''re blistered, finished with Maldon salt and eaten whole. Vegan and gluten free.', 'A clear answer gets a hesitant guest to try them.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0110', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How many skewers come in the Chimichurri Beef Skewers?', null, '["4", "3", "2", "6"]'::jsonb, '["4"]'::jsonb, 'Four skewers of marinated Angus beef, grilled, with a roasted red pepper chimichurri, which is sweeter and milder than the classic herb version.', 'Helps you size the order for the table.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0111', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What tops the Patatas Bravas?', null, '["Truffle oil and Grana Padano", "Cheese sauce and bacon", "Guacamole and sour cream", "Spicy tomato sauce and aioli"]'::jsonb, '["Spicy tomato sauce and aioli"]'::jsonb, 'Fried potatoes topped with a spiced tomato sauce, smoked paprika and aioli: a classic Spanish tapa, made for sharing.', 'A good suggestion for a table ordering drinks and small plates.', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0112', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'On the Sardines Toast, what is escalivada?', null, '["A garlic mayonnaise", "Slow-roasted eggplant, onion and capsicum", "A Spanish anchovy paste", "Pickled fennel"]'::jsonb, '["Slow-roasted eggplant, onion and capsicum"]'::jsonb, 'Escalivada is a Spanish dish of slow-roasted eggplant, onion and capsicum. Two sourdough toasts with escalivada and "Espinaler" baby sardines (about 4 cm long), topped with aioli and shaved fennel.', 'Lets you describe the dish properly instead of just "sardines on toast".', false, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0113', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How many shrimps come in the Garlic Shrimps?', null, '["10", "6", "12", "8"]'::jsonb, '["8"]'::jsonb, 'Eight shrimps cooked in garlic butter with a hint of chili, with tomato cubes and lemon, served with sourdough toast.', 'Guests often ask how big the portion is.', false, 'Full menu descriptions, MM-AR, October 2026, Soups and starters', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0114', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'A guest says their Vitello Tonnato is cold. What do you explain?', null, '["It has waited at the pass too long", "Only the sauce should be cold", "It can be warmed in the oven", "It''s a cold dish by design"]'::jsonb, '["It''s a cold dish by design"]'::jsonb, 'Vitello tonnato is a classic cold dish from Piedmont in northern Italy: thin slices of slow-roasted veal under a creamy tuna sauce with anchovy and capers. It''s served cold on purpose.', 'A confident explanation turns a complaint into a good story about the dish.', false, 'Full menu descriptions, MM-AR, October 2026, Soups and starters', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0115', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'A pregnant guest asks for the Tuna Tartare to be cooked. What do you say?', null, '["Offer it without the stracciatella", "It''s served raw and can''t be cooked to order; suggest a cooked dish instead", "The kitchen can sear it for her", "It''s fine because the tuna is very fresh"]'::jsonb, '["It''s served raw and can''t be cooked to order; suggest a cooked dish instead"]'::jsonb, 'The Tuna Tartare & Stracciatella (R) is hand-cut raw tuna loin. It''s not suitable for pregnant guests and can''t be cooked to order.', 'Guiding the guest to a suitable dish is part of looking after them.', false, 'Full menu descriptions, MM-AR, October 2026, Soups and starters', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0116', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Why does the Seabream Ceviche look cooked when it isn''t?', null, '["It''s lightly steamed", "It''s seared for a few seconds", "The lime in the leche de tigre firms up the fish without heat", "It''s smoked"]'::jsonb, '["The lime in the leche de tigre firms up the fish without heat"]'::jsonb, 'The seabream is raw, cured in leche de tigre (lime juice, chili, onion and the juices from the fish). The acid firms up the surface of the fish without any heat, so it looks cooked but isn''t.', 'Guests who avoid raw fish need to know it''s raw, even if it looks cooked.', false, 'Full menu descriptions, MM-AR, October 2026, Soups and starters', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0117', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'A guest wants the Butcher''s Ciabatta without pork. What do you tell them?', null, '["Leave out the chorizo and it''s pork free", "It can''t be made pork free: the chorizo and the mortadella are both pork", "Swap the turkey ham for beef", "It''s already pork free"]'::jsonb, '["It can''t be made pork free: the chorizo and the mortadella are both pork"]'::jsonb, 'The Butcher''s Ciabatta (P) has turkey ham, pork chorizo and pork mortadella, with provolone, tomato, lettuce, mayonnaise and olive tapenade. Leaving out one item doesn''t make it pork free.', 'A guest who doesn''t eat pork must never get pork by mistake.', false, 'Full menu descriptions, MM-AR, October 2026, Sandwiches and toasts', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0118', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Is the chipotle mayo on the Smoked Pork Belly sandwich hot?', null, '["Only if the guest asks for extra", "It''s sweet, like a honey mayo", "Yes, it''s the hottest sauce we have", "No: chipotle gives smokiness more than heat"]'::jsonb, '["No: chipotle gives smokiness more than heat"]'::jsonb, 'Chipotle is a smoked, dried jalapeño, so it brings smokiness more than heat. Smoked pork belly in a toasted brioche bun with Monterey Jack, slow-roasted tomato, gherkins and chipotle mayo.', 'Guests who avoid spicy food can order it with confidence.', false, 'Full menu descriptions, MM-AR, October 2026, Sandwiches and toasts', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0119', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Why does halloumi work so well in the Crispy Halloumi sandwich?', null, '["It''s a soft cheese that spreads", "It melts like mozzarella", "It has a very high melting point, so it crisps instead of melting", "It''s smoked first"]'::jsonb, '["It has a very high melting point, so it crisps instead of melting"]'::jsonb, 'Halloumi, a cheese from Cyprus, crisps and chars on the outside instead of melting. Here it''s coated in panko and fried, in a brioche bun with tomato relish, pickled cabbage slaw and miso mayo. A vegetarian sandwich.', 'A good line for vegetarian guests choosing a sandwich.', false, 'Full menu descriptions, MM-AR, October 2026, Sandwiches and toasts', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0120', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Is the Chicken Avocado Wrap spicy?', null, '["Very spicy", "Slightly: the chicken is marinated with chili powder and there''s sriracha", "No, it''s completely mild", "Only the side salad is spicy"]'::jsonb, '["Slightly: the chicken is marinated with chili powder and there''s sriracha"]'::jsonb, 'A wheat wrap with avocado, iceberg, pico de gallo, sour cream, sriracha and chicken marinated in olive oil and chili powder. Slightly spicy.', 'Guests who don''t like heat should know before ordering.', false, 'Full menu descriptions, MM-AR, October 2026, Sandwiches and toasts', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0121', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How heavy is the patty in the M/M Black Angus Burger?', null, '["250 g", "180 g", "120 g", "150 g"]'::jsonb, '["180 g"]'::jsonb, 'A classic burger with a thick 180 g prime Angus patty, tomato, grilled onion, gherkins, cheddar and BBQ sauce in a fresh brioche bun.', 'Guests comparing burgers often ask about the patty size.', false, 'Full menu descriptions, MM-AR, October 2026, M/M burgers', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0122', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What is the Veggie Burger patty made from?', null, '["A plant-based meat substitute", "Chickpeas, like falafel", "Quinoa and vegetables, homemade", "Beetroot and lentils"]'::jsonb, '["Quinoa and vegetables, homemade"]'::jsonb, 'A homemade patty of quinoa and vegetables, fried for a crispy bite, with burger sauce, gherkins and iceberg. Marked (V).', 'Vegetarian guests often ask what''s in a veggie patty.', false, 'Full menu descriptions, MM-AR, October 2026, M/M burgers', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0123', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What is the mash in the Bangers and Mash made of?', null, '["Potatoes only", "Sweet potato", "Celeriac", "Potatoes and carrots"]'::jsonb, '["Potatoes and carrots"]'::jsonb, 'Three English pork sausages in a caramelised onion gravy, topped with crispy onion and kale, with a mash of potatoes and carrots.', 'Small details like this make your description sound like you''ve tasted it.', false, 'Full menu descriptions, MM-AR, October 2026, For the love of pork', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0124', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How much is a portion of the M/M Glazed Pork Ribs?', null, '["800 g", "300 g", "400 g", "600 g"]'::jsonb, '["600 g"]'::jsonb, '600 g of homemade slow-cooked pork back ribs, glazed with a smoky BBQ sauce, with coleslaw and roasted potatoes.', 'A big portion: useful when a guest asks if it''s enough or too much.', false, 'Full menu descriptions, MM-AR, October 2026, For the love of pork', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0125', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What is the Prager Schnitzel fried in?', null, '["Olive oil", "Sunflower oil", "Clarified butter", "Beef dripping"]'::jsonb, '["Clarified butter"]'::jsonb, 'The schnitzel is fried in clarified butter for flavour. The breadcrumbs are seasoned with smoked paprika, onion powder and garlic powder. With caper butter, lemon, rocket, cherry tomato, Grana Padano and potato salad. Marked (P).', 'A detail that helps you sell it.', false, 'Full menu descriptions, MM-AR, October 2026, For the love of pork', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0126', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What are the Beer-Braised Pork Cheeks braised in?', null, '["Red wine", "Pork stock only", "Dark Belgian beer (Leffe Brune)", "Apple cider"]'::jsonb, '["Dark Belgian beer (Leffe Brune)"]'::jsonb, 'Pork cheeks braised slowly in Leffe Brune until they fall apart, with mashed potato, pearl onions, baby carrot and green peas. Marked (P, A).', 'Guests who avoid alcohol, even in cooking, need to know.', false, 'Full menu descriptions, MM-AR, October 2026, For the love of pork', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0127', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What is the Cordon Blue Deluxe filled with?', null, '["Pork ham and Comté cheese", "Spinach and feta", "Turkey ham and gouda", "Beef bacon and mozzarella"]'::jsonb, '["Pork ham and Comté cheese"]'::jsonb, 'A chicken breast schnitzel filled with pork ham and Comté, with a truffle cheese sauce, mashed potatoes, broccolini and baby carrot. Marked (P) because of the ham.', 'A chicken dish that contains pork: guests who don''t eat pork must be told.', false, 'Full menu descriptions, MM-AR, October 2026, Meat specials', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0128', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'The Comté in the Cordon Blue Deluxe is made from what kind of milk?', null, '["Pasteurised goat''s milk", "Unpasteurised milk", "Buffalo milk", "Sheep''s milk"]'::jsonb, '["Unpasteurised milk"]'::jsonb, 'Comté is a cheese from the Alps with a mild, slightly sweet taste, made from unpasteurised milk. It''s in the Cordon Blue Deluxe.', 'Some guests, such as pregnant guests, avoid unpasteurised cheese.', false, 'Full menu descriptions, MM-AR, October 2026, Meat specials', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0129', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How is the Belgian Steak Tartare served?', null, '["Seared on the outside, with mash", "Raw: 180 g of beef with cocktail sauce and egg yolk, with Belgian fries", "Raw, on its own without a side", "Cooked medium, with a fried egg"]'::jsonb, '["Raw: 180 g of beef with cocktail sauce and egg yolk, with Belgian fries"]'::jsonb, '180 g of raw beef cut in cubes, seasoned with a cocktail sauce and egg yolk, with cherry tomato, rocket and a thin sourdough toast, served with Belgian fries. Marked (R).', 'Guests must know it''s raw before ordering.', false, 'Full menu descriptions, MM-AR, October 2026, Meat specials', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0130', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'A guest wants a steak that''s lean and very tender. Which do you recommend?', null, '["Black Angus Grilled Tenderloin", "Steak and Fries (rump)", "Grilled Wagyu Striploin", "Grilled Rib Eye"]'::jsonb, '["Black Angus Grilled Tenderloin"]'::jsonb, 'The tenderloin is very lean and very tender. The rib eye and Wagyu striploin have more fat for flavour. The rump in Steak and Fries is lean too, but not the most tender cut.', 'Matching the cut to the guest''s taste gets the steak right first time.', false, 'Full menu descriptions, MM-AR, October 2026, From the farm', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0131', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'A guest orders the tenderloin well done. What do you tell them?', null, '["Well done isn''t possible on the tenderloin", "It''s a thick cut, so well done may take at least 25 minutes", "It will be cut in half to cook faster", "It takes the same time as medium"]'::jsonb, '["It''s a thick cut, so well done may take at least 25 minutes"]'::jsonb, 'The Black Angus tenderloin is a thick piece of meat. For well done, tell the guest it may take at least 25 minutes.', 'Setting the time up front avoids a long, unexplained wait.', false, 'Full menu descriptions, MM-AR, October 2026, From the farm', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0132', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What is Wagyu known for?', null, '["Being very lean", "Being grass fed only", "Being dry aged for 60 days", "High fat marbling through the meat, for flavour and a soft texture"]'::jsonb, '["High fat marbling through the meat, for flavour and a soft texture"]'::jsonb, 'Our Grilled Wagyu Striploin is Australian "Westholme" Wagyu, marbling 4 to 5. Wagyu is known for its fat marbling, which adds flavour and a soft texture. It comes with red wine shallots and a Padron pepper.', 'Explains the price difference to a guest choosing a steak.', false, 'Full menu descriptions, MM-AR, October 2026, From the farm', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0133', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Which steak comes in the Steak and Fries?', null, '["200 g Australian grain-fed Angus rump", "Black Angus tenderloin", "Prime Angus rib eye", "Wagyu striploin"]'::jsonb, '["200 g Australian grain-fed Angus rump"]'::jsonb, 'Steak and Fries is a grilled 200 g Australian Angus rump, grain fed for 250 days: a simple steak without fat, with good flavour, though not the softest cut.', 'Helps you set the right expectation for the guest.', false, 'Full menu descriptions, MM-AR, October 2026, From the farm', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0134', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What''s the difference between Belgian fries and skinny fries?', null, '["Belgian fries are thin; skinny fries are thick", "Belgian fries are thick (13 mm) and double cooked; skinny fries are thin (7 mm)", "Belgian fries are made from sweet potato", "Only the cooking oil is different"]'::jsonb, '["Belgian fries are thick (13 mm) and double cooked; skinny fries are thin (7 mm)"]'::jsonb, 'Belgian fries are a thick 13 mm cut, double cooked. Skinny fries are a crispy 7 mm cut. Both are always served with mayo and ketchup on the side.', 'Guests often ask which to choose.', false, 'Full menu descriptions, MM-AR, October 2026, Sides', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0135', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'A guest who doesn''t take alcohol wants the Fish and Chips. What can you offer?', null, '["A grilled cod, ready at the same time", "Nothing: the batter always has beer", "The alcohol cooks off, so it''s fine", "A batter without alcohol, which takes about 30 minutes"]'::jsonb, '["A batter without alcohol, which takes about 30 minutes"]'::jsonb, 'The Fish and Chips (A) has a beer batter. A batter without alcohol can be made, but it takes about 30 minutes.', 'Offer the option and the timing, so the guest can decide.', false, 'Full menu descriptions, MM-AR, October 2026, From the sea', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0136', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What is the sauce on the Salmon Fillet?', null, '["Bisque", "Hollandaise", "Béarnaise", "Beurre blanc, a white wine butter sauce"]'::jsonb, '["Beurre blanc, a white wine butter sauce"]'::jsonb, 'Skin-on salmon with a beurre blanc (white wine butter sauce), parsley potatoes, leeks, asparagus and cherry tomato. Marked (A) because of the wine.', 'Guests who avoid alcohol need to know about the sauce.', false, 'Full menu descriptions, MM-AR, October 2026, From the sea', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0137', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What should you ask a guest ordering the Tuna Steak?', null, '["Which sauce they want from the steak list", "Whether they want it raw", "How they''d like it cooked: it''s best pink in the middle", "Nothing: it''s always cooked through"]'::jsonb, '["How they''d like it cooked: it''s best pink in the middle"]'::jsonb, 'Tuna is at its best pink in the middle; cooked all the way through it goes dry. Ask how the guest wants it. With red pepper chimichurri, lemon and a fennel citrus salad.', 'Asking first gets the dish right for the guest.', false, 'Full menu descriptions, MM-AR, October 2026, From the sea', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0138', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Can the mussels be made without white wine?', null, '["No, it''s part of every sauce", "Only the Thai Curry", "Yes, the white wine can be left out on request", "Only for the 1 kg portion"]'::jsonb, '["Yes, the white wine can be left out on request"]'::jsonb, 'All our mussels are made with white wine as standard, which is why they''re marked (A), but it can be left out on request.', 'Lets guests who avoid alcohol still enjoy the mussels.', false, 'Full menu descriptions, MM-AR, October 2026, Mussels', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0139', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How many cheeses are in the béchamel of the Pulled Beef Mac & Cheese?', null, '["3", "4", "5", "6"]'::jsonb, '["6"]'::jsonb, 'Chifferi pasta in a six-cheese béchamel (Emmental, Comté, Grana Padano, Old Farmdal, mature cheddar and gorgonzola) with pulled beef, finished with gremolata and truffle oil.', 'A strong selling point for cheese lovers.', false, 'Full menu descriptions, MM-AR, October 2026, Pasta', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0140', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Why are the Argentinian red shrimp in the linguini red before cooking?', null, '["They''re marinated in paprika", "They''re naturally red, unlike most prawns", "They''re cooked before delivery", "They''re smoked"]'::jsonb, '["They''re naturally red, unlike most prawns"]'::jsonb, 'Argentinian red shrimp are red before cooking, and sweeter and softer than tiger prawns. The bisque is made from their shells, so the whole sauce carries the shrimp flavour.', 'A detail guests remember, and a reason to try the dish.', false, 'Full menu descriptions, MM-AR, October 2026, Pasta', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0141', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What makes the Green Risotto green?', null, '["Basil pesto", "Pea purée", "A spinach and green herb paste", "Matcha"]'::jsonb, '["A spinach and green herb paste"]'::jsonb, 'A new version of our risotto, made green with a spinach and green herb paste, with asparagus, green peas and zucchini, topped with soft goat cheese and half-dried cherry tomatoes. Marked (V, GF).', 'Helps you describe a vegetarian main with confidence.', false, 'Full menu descriptions, MM-AR, October 2026, Vegetarian', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0142', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What does "Quatro Stagione" mean?', null, '["Four cheeses", "Four corners", "Four seasons", "Four meats"]'::jsonb, '["Four seasons"]'::jsonb, 'Quattro stagioni is Italian for four seasons: mozzarella, tomato sauce, artichokes, mushrooms, onion, turkey ham and olives. Quattro formaggi means four cheeses.', 'Guests often mix the two up.', false, 'Full menu descriptions, MM-AR, October 2026, M/M stone baked pizzas', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0143', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'multi', 'Which of these pizzas contain pork? Pick all that apply.', null, '["Meat Lover", "Quatro Stagione", "Figs and Bacon", "Diavola", "Prosciutto & Rocket", "Pepperoni"]'::jsonb, '["Prosciutto & Rocket", "Meat Lover"]'::jsonb, 'Prosciutto & Rocket and Meat Lover have pork prosciutto, marked (P). Diavola has beef chorizo, Pepperoni has beef salami, Figs and Bacon has beef bacon and Quatro Stagione has turkey ham.', 'A guest who doesn''t eat pork must never get pork by mistake.', false, 'Full menu descriptions, MM-AR, October 2026, M/M stone baked pizzas', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0144', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Which pizza is made to be quite spicy?', null, '["Margarita", "Quatro Formaggi", "Alla Pollo", "Caliente"]'::jsonb, '["Caliente"]'::jsonb, 'The Caliente has beef ''nduja (a spiced beef mince mix), beef pepperoni, Roquito chilies, tomato sauce, mozzarella and rocket. It''s meant to be quite spicy.', 'Warn guests who don''t like heat, and point spice lovers to it.', false, 'Full menu descriptions, MM-AR, October 2026, M/M stone baked pizzas', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0145', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'multi', 'Which pizzas come with cold, fresh toppings? Pick all that apply.', null, '["Tartuffo", "Figs and Bacon", "Crispy Carpaccio", "Burrata", "Pescatore"]'::jsonb, '["Crispy Carpaccio", "Burrata"]'::jsonb, 'The Crispy Carpaccio (raw beef carpaccio, tomato, rocket, Grana Padano) and the Burrata (burrata, tomatoes, basil oil, olive tapenade) have cold toppings on a crispy base.', 'Guests expecting a hot pizza should know before ordering.', false, 'Full menu descriptions, MM-AR, October 2026, Sourdough and crispy pizzas', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0146', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'How long does Le Moelleux au Chocolat take?', null, '["2 minutes: it''s ready to serve", "30 minutes", "About 15 minutes: it''s made to order", "It''s served cold, straight away"]'::jsonb, '["About 15 minutes: it''s made to order"]'::jsonb, 'Our moelleux, a hot soft-centred chocolate cake, is made to order and takes about 15 minutes. Served with vanilla ice cream and red fruit.', 'Offer it early, or let the guest know about the wait.', false, 'Full menu descriptions, MM-AR, October 2026, Desserts', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-lunch-dinner-0147', 'food', 'lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'What ice cream comes with the Profiteroles?', null, '["Chocolate", "Speculoos", "Salted caramel", "Vanilla"]'::jsonb, '["Salted caramel"]'::jsonb, 'Choux pastry profiteroles filled with vanilla pastry cream, with salted caramel ice cream and Valrhona chocolate sauce. Good for sharing.', 'A good dessert to suggest for the table to share.', false, 'Full menu descriptions, MM-AR, October 2026, Desserts', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0100', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'Unless the guest asks otherwise, how are the eggs in Simply Your Way served?', null, '["Poached", "Scrambled", "Sunny side up", "Boiled"]'::jsonb, '["Sunny side up"]'::jsonb, 'Simply Your Way comes with sunny side up eggs as standard. The guest can change to fried, boiled, poached or over easy.', 'Ask the guest, but know the default if they don''t mind.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: omelets and eggs', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0101', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'Do you ask how the minute steak should be cooked in the M/M Steak Breakfast Stack?', null, '["Only if the guest is pregnant", "Yes, always ask for the doneness", "No: it''s sliced thin and grilled 1 minute each side", "Yes, it''s cooked to order like a steak main"]'::jsonb, '["No: it''s sliced thin and grilled 1 minute each side"]'::jsonb, 'A minute steak is thinly sliced and grilled for 1 minute each side, so there''s no need to ask for doneness. With a homemade hash brown, poached egg, spinach, mushroom, caramelised onion and béarnaise.', 'Saves a question at the table and sets the right expectation.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: omelets and eggs', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0102', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What are Huevos Estrellados?', null, '["Scrambled eggs with chorizo on toast", "A folded omelet with potato", "Eggs baked in a spiced tomato sauce", "Fried potato cubes with caramelised onion, garlic and parsley, topped with 3 eggs"]'::jsonb, '["Fried potato cubes with caramelised onion, garlic and parsley, topped with 3 eggs"]'::jsonb, 'Huevos Estrellados are fried potato cubes sautéed with caramelised onion, garlic and parsley, topped with 3 eggs.', 'A Spanish name guests often ask about.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: omelets and eggs', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0103', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'How are the eggs cooked in the Shakshuka?', null, '["Scrambled into the sauce", "Fried and served on the side", "Inside the spiced tomato sauce, in an oven dish", "Poached separately and placed on top"]'::jsonb, '["Inside the spiced tomato sauce, in an oven dish"]'::jsonb, 'Two eggs are cooked inside spicy crushed cherry tomatoes in an oven dish, seasoned with coriander and cumin, served with sourdough toast and roasted cherry tomato.', 'Helps you describe the dish to guests who don''t know it.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: omelets and eggs', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0104', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'How much crab meat is in the Crab Omelet?', null, '["60 g", "30 g", "100 g", "150 g"]'::jsonb, '["60 g"]'::jsonb, 'The Crab Omelet has 60 g of crab meat, with shallot, ginger, spring onion, chili and sriracha, served with sourdough toast. Its flavour leans towards an Asian breakfast dish.', 'Guests paying for crab like to know how much is in it.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: omelets and eggs', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0105', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is the bacon mayo on the Breakfast Bun?', null, '["Mayonnaise with beef bacon flavouring", "Mayonnaise with chopped bacon pieces", "Mayonnaise made with bacon fat instead of oil", "A smoky vegan mayo"]'::jsonb, '["Mayonnaise made with bacon fat instead of oil"]'::jsonb, 'Bacon mayo is a mayonnaise made with the fat from bacon instead of oil. The Breakfast Bun is a brioche bun with hash brown, streaky bacon, avocado and bacon mayo.', 'The sauce itself is made with bacon fat, and the dish is listed as containing pork.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: omelets and eggs', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0106', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'Is the Smoked Salmon and Asparagus Omelet folded?', null, '["No, it''s an open omelet", "It''s scrambled, not an omelet", "It''s rolled like a crêpe", "Yes, folded in half"]'::jsonb, '["No, it''s an open omelet"]'::jsonb, 'An open omelet with green asparagus and smoked salmon, topped with green herbs (dill, parsley, tarragon) and lemon. Bread is served on the side.', 'Describes what the guest will see when it arrives.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: omelets and eggs', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0107', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'A guest wants The Full English without pork. What changes?', null, '["Only the bacon changes", "It can''t be made without pork", "Everything switches to beef, including the black pudding", "The bacon and sausage switch to beef, and the black pudding comes off"]'::jsonb, '["The bacon and sausage switch to beef, and the black pudding comes off"]'::jsonb, 'The pork can be changed to beef for the bacon and sausage only. For a beef Full English, the black pudding is removed.', 'A guest who doesn''t eat pork must never get pork by mistake.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: traditional breakfast', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0108', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What''s the general rule for changes to The Full English?', null, '["Only the eggs can be changed", "Swap vegetable items for vegetable items, and meat for meat", "No changes at all", "Any item can be swapped for any other"]'::jsonb, '["Swap vegetable items for vegetable items, and meat for meat"]'::jsonb, 'Some adjustments are possible, but the general rule is that we only swap vegetable items for vegetable items and meat for meat.', 'Lets you say yes quickly to fair requests.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: traditional breakfast', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0109', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'Which croissants can the guest choose with the M/M Breakfast?', null, '["Almond or butter croissant", "Any croissant from the bakery", "Butter croissant or pain au chocolat", "Butter croissant only"]'::jsonb, '["Butter croissant or pain au chocolat"]'::jsonb, 'With the M/M Breakfast there''s a choice of butter croissant or pain au chocolat. It''s available in a pork or a halal version.', 'Ask the guest so the right one goes out first time.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: traditional breakfast', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0110', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'How is the spicy hollandaise on the Pulled Beef Benedict made?', null, '["Chipotle mayo", "Béarnaise with chili flakes", "Hollandaise mixed with sriracha", "Hollandaise with jalapeño"]'::jsonb, '["Hollandaise mixed with sriracha"]'::jsonb, 'We mix our hollandaise with sriracha to make a chili hollandaise. With 6-hour slow-cooked BBQ pulled beef, brioche, poached eggs and M/M chili beans.', 'Guests who don''t like heat should know about the sauce.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: benedicts', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0111', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'How is the "vegan scramble" in the Vegan Breakfast made?', null, '["Tofu pan-fried with spices and turmeric", "Scrambled egg whites", "Chickpea flour batter", "Crushed avocado and beans"]'::jsonb, '["Tofu pan-fried with spices and turmeric"]'::jsonb, 'We pan-fry tofu with spices and turmeric to make a vegan scramble, served with tomato, mushroom, avocado, toast, beans and hash brown.', 'Vegan guests often ask what replaces the eggs.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: healthy section', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0112', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is açaí, in the Tropical Açaí Bowl?', null, '["A dragon fruit purée", "A Brazilian yoghurt", "A type of granola", "A small purple berry from the Amazon, served frozen as a purée"]'::jsonb, '["A small purple berry from the Amazon, served frozen as a purée"]'::jsonb, 'Açaí is a small purple berry from the Amazon with a mild, slightly earthy flavour, usually served frozen as a smooth purée. Ours comes with passion fruit, mango, banana, dragon fruit, strawberry, mint and granola.', 'Guests often ask what açaí is.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: healthy section', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0113', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is the Chia Pudding made with?', null, '["Coconut milk and chia seeds", "Cow''s milk and rice", "Almond milk and oats", "Greek yoghurt and chia seeds"]'::jsonb, '["Coconut milk and chia seeds"]'::jsonb, 'A coconut milk and chia seed pudding topped with berry compote and fresh fruit.', 'Guests avoiding dairy often ask what it''s made with.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: healthy section', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0114', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is the Greek Yoghurt Crème?', null, '["Greek yoghurt with garlic and mint", "Plain yoghurt with honey", "Whipped cream flavoured with Greek yoghurt, with fresh mango, passion fruit and granola", "Frozen yoghurt with berries"]'::jsonb, '["Whipped cream flavoured with Greek yoghurt, with fresh mango, passion fruit and granola"]'::jsonb, 'Whipped cream flavoured with Greek yoghurt, with fresh mango and passion fruit, topped with our homemade granola.', 'Lets you describe it properly: it''s richer than plain yoghurt.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: healthy section', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0115', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What''s different about the brioche in the Chocolate French Toast?', null, '["It''s made with croissant dough", "It''s dipped in melted chocolate", "Cocoa is added to the brioche dough", "It''s filled with chocolate spread"]'::jsonb, '["Cocoa is added to the brioche dough"]'::jsonb, 'We add cocoa to our classic brioche dough, then make a French toast, served with chocolate ganache, raspberry compote, whipped cream, chocolate crumble and toasted almonds.', 'A detail that makes the dish easy to sell.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: pancakes and sweets', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0116', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What kind of waffle do we serve?', null, '["Waffle cone", "Liège waffle", "American waffle", "Brussels waffle"]'::jsonb, '["Brussels waffle"]'::jsonb, 'Both the Strawberries and Cream Waffle and the Belgian Chocolate Waffle use a Brussels waffle.', 'Guests from Belgium will ask.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: pancakes and sweets', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-breakfast-0117', 'food', 'breakfast', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'On the Farmers Omelet, can the pork bacon be changed?', null, '["No, it''s always pork", "Only by removing the bacon", "Yes, to turkey ham", "Yes, to beef bacon"]'::jsonb, '["Yes, to beef bacon"]'::jsonb, 'The Farmers Omelet (P) has pork bacon, tomato, potato, mushrooms and caramelised onion. The pork bacon can be changed to beef bacon.', 'Lets guests who don''t eat pork still enjoy the dish.', false, 'Full menu descriptions, MM-AR, October 2026, Breakfast: omelets and eggs', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0001', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'On our menu, what does "confit" mean?', null, '["Smoked over wood", "Cured in salt and sugar", "Cooked slowly, submerged in fat", "Grilled over charcoal"]'::jsonb, '["Cooked slowly, submerged in fat"]'::jsonb, 'Confit means cooked slowly submerged in fat, originally a way of preserving food in south-west France. Our Confit Duck Leg is cooked this way until it comes off the bone, then crisped up to order. Confit garlic is cooked slowly in oil until soft and sweet.', 'Guests often ask, and "cooked slowly in its own fat" sells the dish.', false, 'Full menu descriptions, MM-AR, October 2026, Confit Duck Leg', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0002', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is "leche de tigre"?', null, '["The citrus marinade a ceviche is cured in", "A coconut milk dressing", "A spicy mayonnaise", "A Peruvian tiger prawn sauce"]'::jsonb, '["The citrus marinade a ceviche is cured in"]'::jsonb, 'Leche de tigre (tiger''s milk) is the citrus marinade a ceviche is cured in: lime juice, chili, onion and the juices from the fish. In Peru it''s also drunk on its own as a shot.', 'Lets you explain the ceviche in plain words.', false, 'Full menu descriptions, MM-AR, October 2026, Seabream Ceviche', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0003', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is aioli?', null, '["A tomato salsa", "A garlic mayonnaise", "A basil sauce", "A yoghurt and cucumber dip"]'::jsonb, '["A garlic mayonnaise"]'::jsonb, 'Aioli is a garlic mayonnaise. Ours comes with the Crispy Calamari and Patatas Bravas; the seabream has a saffron aioli.', 'One of the most common words on our menu.', false, 'Full menu descriptions, MM-AR, October 2026, Crispy calamari, seabream', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0004', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What''s the difference between potato boulangère and gratin dauphinois?', null, '["They''re the same dish", "Boulangère has cheese; dauphinois doesn''t", "Boulangère is mashed; dauphinois is roasted", "Boulangère is baked in stock; dauphinois is baked in cream"]'::jsonb, '["Boulangère is baked in stock; dauphinois is baked in cream"]'::jsonb, 'Potato boulangère is layered sliced potato and caramelised onion baked in stock, the lighter cousin of gratin dauphinois, which is baked in cream. The name comes from villagers taking the dish to the baker (boulanger) to cook in his oven. It comes with our Lamb Chops.', 'A nice story to tell, and it tells a guest the dish is lighter than they might expect.', false, 'Full menu descriptions, MM-AR, October 2026, Lamb Chops', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0005', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is chimichurri?', null, '["A Spanish garlic mayonnaise", "An Italian basil pesto", "An Argentinian herb sauce of parsley, garlic, oregano, vinegar and oil", "A Mexican chili salsa"]'::jsonb, '["An Argentinian herb sauce of parsley, garlic, oregano, vinegar and oil"]'::jsonb, 'Chimichurri is an Argentinian herb sauce, usually parsley, garlic, oregano, vinegar and oil. Our version has roasted red pepper in it, which makes it sweeter and milder. It''s on the Chimichurri Beef Skewers and the Tuna Steak.', 'Helps you describe two of our dishes.', false, 'Full menu descriptions, MM-AR, October 2026, Chimichurri Beef Skewers, Tuna Steak', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0006', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is pico de gallo?', null, '["A fresh, uncooked salsa of chopped tomato, onion and lime", "A smashed avocado dip", "A cooked chili sauce", "A sour cream and chive dip"]'::jsonb, '["A fresh, uncooked salsa of chopped tomato, onion and lime"]'::jsonb, 'Pico de gallo is a fresh uncooked salsa of chopped tomato, onion and lime (ours also has green capsicum on the nachos). The name translates as "rooster''s beak". It''s on the M/M Fish Taco, M/M Nacho''s and Chicken Avocado Wrap.', 'A word guests see on three dishes.', false, 'Full menu descriptions, MM-AR, October 2026, Fish taco, nachos, wrap', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0007', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is stracciatella, the cheese?', null, '["The soft, creamy inside of a burrata: torn mozzarella mixed with cream", "A hard aged cheese for grating", "A goat cheese from France", "A blue cheese"]'::jsonb, '["The soft, creamy inside of a burrata: torn mozzarella mixed with cream"]'::jsonb, 'Stracciatella is the soft, creamy inside of a burrata: torn mozzarella mixed with cream. It''s served with our Tuna Tartare.', 'Guests often know burrata but not stracciatella.', false, 'Full menu descriptions, MM-AR, October 2026, Tuna Tartare & Stracciatella', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0008', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is guanciale?', null, '["A spicy sausage", "Cured pork cheek", "Cured beef", "A sheep''s milk cheese"]'::jsonb, '["Cured pork cheek"]'::jsonb, 'Guanciale is cured pork cheek, fattier and more delicate than bacon. It''s in the Rigatoni Amatriciana, marked (P).', 'A pork ingredient with an Italian name: guests who don''t eat pork may not recognise it.', false, 'Full menu descriptions, MM-AR, October 2026, Rigatoni Amatriciana', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0009', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is ''nduja?', null, '["A sweet pepper paste", "A mild Italian ham", "A soft, spreadable, spicy salami from Calabria", "A fennel sausage"]'::jsonb, '["A soft, spreadable, spicy salami from Calabria"]'::jsonb, '''Nduja is a soft, spreadable, spicy salami from Calabria. In our porchetta it melts into the pork as it roasts and carries real heat. The Caliente pizza uses a beef ''nduja.', 'Warns guests about the heat.', false, 'Full menu descriptions, MM-AR, October 2026, ''Nduja & Fennel Stuffed Porchetta', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0010', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is porchetta?', null, '["A pork sausage from Bologna", "Cured ham from the leg", "Cured pork neck", "Italian pork belly, rolled and slow roasted"]'::jsonb, '["Italian pork belly, rolled and slow roasted"]'::jsonb, 'Porchetta is Italian pork belly rolled around a seasoned filling and slow roasted so the skin crisps up. It''s on the charcuterie platter and is the main of the ''Nduja & Fennel Stuffed Porchetta.', 'Lets you explain a pork dish clearly.', false, 'Full menu descriptions, MM-AR, October 2026, Charcuterie, porchetta', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0011', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is pane carasau?', null, '["A very thin, crisp flatbread from Sardinia", "A soft focaccia", "A breadstick from Turin", "A rye cracker from Belgium"]'::jsonb, '["A very thin, crisp flatbread from Sardinia"]'::jsonb, 'Pane carasau is a very thin crisp flatbread from Sardinia, sometimes called "carta da musica" (sheet music) because it''s thin enough to read through. It comes with the charcuterie platter.', 'A lovely detail to share at the table.', false, 'Full menu descriptions, MM-AR, October 2026, M/M Pork Charcuterie Platter', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0012', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is coppa?', null, '["Cured pork neck, marbled and sweeter than Parma ham", "Smoked turkey", "A finely ground pork sausage", "Cured beef"]'::jsonb, '["Cured pork neck, marbled and sweeter than Parma ham"]'::jsonb, 'Coppa is cured pork neck: marbled, and sweeter than Parma ham. Mortadella is a large, finely ground pork sausage from Bologna. Both are on the charcuterie platter.', 'Helps you describe the platter item by item.', false, 'Full menu descriptions, MM-AR, October 2026, M/M Pork Charcuterie Platter', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0013', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is gremolata?', null, '["A truffle paste", "Crispy breadcrumbs", "Chopped parsley, garlic and lemon zest", "Grated Grana Padano"]'::jsonb, '["Chopped parsley, garlic and lemon zest"]'::jsonb, 'Gremolata is chopped parsley, garlic and lemon zest, added at the end to cut through the richness of the cheese on the Pulled Beef Mac & Cheese.', 'Explains why the dish isn''t too heavy.', false, 'Full menu descriptions, MM-AR, October 2026, Pulled Beef Mac & Cheese', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0014', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is béchamel?', null, '["A white sauce of butter, flour and milk", "A brown sauce made from stock", "An egg yolk and butter sauce", "A tomato sauce"]'::jsonb, '["A white sauce of butter, flour and milk"]'::jsonb, 'Béchamel is a white sauce made from butter, flour and milk. Our mac & cheese uses a six-cheese béchamel.', 'A basic sauce that comes up often.', false, 'Full menu descriptions, MM-AR, October 2026, Pulled Beef Mac & Cheese', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0015', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is ganache?', null, '["A sponge cake", "A filling made from chocolate, cream and butter", "A meringue topping", "A caramel sauce"]'::jsonb, '["A filling made from chocolate, cream and butter"]'::jsonb, 'Ganache is a classic pastry filling made from chocolate, cream and butter. It''s on the Chocolate French Toast.', 'Helps you describe a dessert-style breakfast.', false, 'Full menu descriptions, MM-AR, October 2026, Chocolate French Toast', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0016', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is choux pastry?', null, '["A fried dough", "A flaky layered pastry", "A shortcrust tart base", "A light baked dough used for éclairs and profiteroles"]'::jsonb, '["A light baked dough used for éclairs and profiteroles"]'::jsonb, 'Choux pastry is a light baked dough, used for éclairs, Paris-Brest and profiteroles.', 'Guests sharing the Profiteroles may ask.', false, 'Full menu descriptions, MM-AR, October 2026, Profiteroles', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0017', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is a Tarte Tatin?', null, '["A chocolate tart", "A tart filled with custard", "An upside-down tart of caramelised apples on puff pastry", "A lemon meringue tart"]'::jsonb, '["An upside-down tart of caramelised apples on puff pastry"]'::jsonb, 'Tarte Tatin is an upside-down tart of caramelised apples (Royal Gala) with a crispy puff pastry base. Good for sharing.', 'A French classic many guests have heard of but can''t describe.', false, 'Full menu descriptions, MM-AR, October 2026, Tarte Tatin', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0018', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is tzatziki?', null, '["A feta and olive spread", "A chickpea dip", "A smoked eggplant dip", "A dip of Greek yoghurt, cucumber, garlic and green herbs"]'::jsonb, '["A dip of Greek yoghurt, cucumber, garlic and green herbs"]'::jsonb, 'Tzatziki is a dip made from Greek yoghurt, cucumber, garlic and green herbs. It''s in the Mediterranean Power Bowl.', 'Vegetarian guests often ask what''s in the bowl.', false, 'Full menu descriptions, MM-AR, October 2026, Mediterranean Power Bowl', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0019', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is guacamole?', null, '["Mashed peas with mint", "A green herb mayonnaise", "A green chili sauce", "Crushed ripe avocado seasoned with lime, tabasco, pepper and salt"]'::jsonb, '["Crushed ripe avocado seasoned with lime, tabasco, pepper and salt"]'::jsonb, 'Guacamole is a dip made by crushing ripe avocados and seasoning them with lime juice, tabasco, pepper and salt. It''s on the M/M Nacho''s.', 'A common question at the table.', false, 'Full menu descriptions, MM-AR, October 2026, M/M Nacho''s', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0020', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is feta?', null, '["A hard cow''s milk cheese", "A soft, slightly salty cheese made from sheep''s milk", "A blue cheese", "A fresh goat cheese"]'::jsonb, '["A soft, slightly salty cheese made from sheep''s milk"]'::jsonb, 'Feta is a soft cheese made from sheep''s milk, with a slightly salty flavour. It''s on the Roasted Beetroot and Feta salad and the Mediterranean Power Bowl.', 'Helps guests choose between our cheese salads.', false, 'Full menu descriptions, MM-AR, October 2026, Roasted Beetroot and Feta', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0021', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is miso?', null, '["A Japanese mustard", "A seaweed seasoning", "A fermented soybean paste", "A rice vinegar"]'::jsonb, '["A fermented soybean paste"]'::jsonb, 'Miso is a fermented soybean paste. In the Crispy Halloumi it makes the mayonnaise savoury and deep rather than sweet.', 'Explains an unfamiliar word on the menu.', false, 'Full menu descriptions, MM-AR, October 2026, Crispy Halloumi', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0022', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What makes béarnaise different from hollandaise?', null, '["Béarnaise is made with cream instead of butter", "Béarnaise has no egg yolk", "Béarnaise has tarragon and shallots", "Béarnaise is spicy"]'::jsonb, '["Béarnaise has tarragon and shallots"]'::jsonb, 'Both are egg yolk and butter sauces. Béarnaise adds shallots and tarragon; our hollandaise has cream, vinegar or lemon juice and a dash of cayenne. The Belgian Benedict is the only benedict with béarnaise.', 'Guests choosing a steak sauce or a benedict often ask.', false, 'Full menu descriptions, MM-AR, October 2026, Steak sauces, breakfast', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0023', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is sriracha?', null, '["A very hot habanero sauce", "A sweet soy glaze", "A smoked paprika oil", "A chili sauce of red chili, garlic and vinegar, moderate heat with some sweetness"]'::jsonb, '["A chili sauce of red chili, garlic and vinegar, moderate heat with some sweetness"]'::jsonb, 'Sriracha is a chili sauce made from red chili, garlic and vinegar. It brings a moderate heat with some sweetness.', 'Guests who avoid spicy food will want to know.', false, 'Full menu descriptions, MM-AR, October 2026, Fish taco, wrap, crab omelet', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0024', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'multi', 'What are peas à la française cooked with? Pick all that apply.', null, '["Lettuce", "Cream", "Mint", "Pearl onion", "White wine", "Pork bacon"]'::jsonb, '["White wine", "Lettuce", "Pearl onion", "Pork bacon"]'::jsonb, 'Peas à la française are peas cooked with white wine, lettuce, pearl onion and pork bacon. They come with the ''Nduja & Fennel Stuffed Porchetta (P, A).', 'The side itself contains pork and alcohol.', false, 'Full menu descriptions, MM-AR, October 2026, ''Nduja & Fennel Stuffed Porchetta', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026.', 'review', 'Claude (draft for David)'),
  ('food-menu-words-0025', 'food', 'menu-words', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'What is a bisque?', null, '["A rich, creamy sauce made from roasted shellfish shells", "A cheese sauce", "A white wine butter sauce", "A clear vegetable broth"]'::jsonb, '["A rich, creamy sauce made from roasted shellfish shells"]'::jsonb, 'A bisque is a rich creamy sauce made from shellfish shells (shrimp), roasted, simmered and strained. It''s why the Cod Fillet carries the (S) mark, and it''s the base of the Red Shrimp Linguini sauce.', 'A guest with a shellfish allergy can''t have a dish with bisque.', true, 'Full menu descriptions, MM-AR, October 2026, Cod Fillet, Red Shrimp Linguini', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('food-allergens-lunch-dinner-0100', 'food', 'allergens-lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'A guest with a shellfish allergy wants the Cod Fillet. What do you tell them?', null, '["It''s fine: cod is a fish, not shellfish", "Not as it''s served: the bisque sauce is made from shrimp shells, so the kitchen would need to change the sauce", "Only the pak choy needs to come off", "It''s fine if they leave the sauce on the side"]'::jsonb, '["Not as it''s served: the bisque sauce is made from shrimp shells, so the kitchen would need to change the sauce"]'::jsonb, 'The Cod Fillet (A, S) is finished with a bisque, made from shrimp shells. A guest with a shellfish allergy can''t have it unless the kitchen changes the sauce. Always tell the kitchen about an allergy.', 'A fish dish that contains shellfish is easy to miss.', true, 'Full menu descriptions, MM-AR, October 2026, From the sea', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('food-allergens-lunch-dinner-0101', 'food', 'allergens-lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'The Chimichurri Beef Skewers list which allergen, and why?', null, '["Fish, from the Worcestershire sauce", "Milk, from a butter glaze", "Nuts, from the chimichurri", "Gluten, from the marinade"]'::jsonb, '["Fish, from the Worcestershire sauce"]'::jsonb, 'The menu lists fish for the Chimichurri Beef Skewers because of the Worcestershire sauce, which contains anchovy.', 'A beef dish with a fish allergen: a guest with a fish allergy wouldn''t expect it.', true, 'Full menu descriptions, MM-AR, October 2026, Sharing', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('food-allergens-lunch-dinner-0102', 'food', 'allergens-lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'A guest wants the Classic Caesar but can''t have anchovy. What can you tell them?', null, '["Swap to the French dressing only", "The kitchen also makes a batch of dressing without anchovy", "The dressing can''t be changed", "Leave out the croutons instead"]'::jsonb, '["The kitchen also makes a batch of dressing without anchovy"]'::jsonb, 'Our Caesar dressing contains anchovy, egg and Grana Padano. The kitchen also makes a batch without anchovy. Always tell the kitchen about the allergy.', 'Lets a guest with a fish allergy still order the Caesar, safely.', true, 'Full menu descriptions, MM-AR, October 2026, Salads', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('food-allergens-lunch-dinner-0103', 'food', 'allergens-lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Can the Maison Mash be made dairy free?', null, '["No: it''s made with milk and butter", "Only the large portion", "Yes, with oat milk", "Yes, with olive oil instead"]'::jsonb, '["No: it''s made with milk and butter"]'::jsonb, 'The Maison Mash is made with milk and butter for a rich, creamy texture and can''t be made dairy free. The oven roasted potatoes are roasted in butter and can''t be made dairy free either.', 'Offer a different side to a guest who can''t have dairy.', true, 'Full menu descriptions, MM-AR, October 2026, Sides', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('food-allergens-lunch-dinner-0104', 'food', 'allergens-lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'A guest who can''t have dairy wants the Sautéed Seasonal Vegetables. What do you say?', null, '["They can''t be made dairy free", "Only the carrots are dairy free", "They can be cooked in olive oil instead of butter", "They''re already dairy free"]'::jsonb, '["They can be cooked in olive oil instead of butter"]'::jsonb, 'The vegetables (usually French beans, broccoli and carrot) are sautéed in butter as standard; the butter can be changed to olive oil to make them dairy free. Tell the kitchen.', 'A simple change that lets the guest have a side safely.', true, 'Full menu descriptions, MM-AR, October 2026, Sides', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('food-allergens-lunch-dinner-0105', 'food', 'allergens-lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Why does the parsley butter on the Escargots de Bourgogne contain gluten?', null, '["It doesn''t: only the toast does", "It''s mixed with our sourdough bread", "It contains beer", "It''s thickened with flour"]'::jsonb, '["It''s mixed with our sourdough bread"]'::jsonb, 'The parsley butter is made by mixing butter with our sourdough bread, garlic and parsley, then piped into the shells with the snails. So gluten is in the butter, not only in the toast on the side.', 'Leaving the toast off doesn''t make the dish gluten free.', true, 'Full menu descriptions, MM-AR, October 2026, Soups and starters', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('food-allergens-lunch-dinner-0106', 'food', 'allergens-lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'Which allergen does the Lamb Chops'' dry rub add?', null, '["Nuts", "Mustard", "Celery", "Sesame"]'::jsonb, '["Sesame"]'::jsonb, 'The Lamb Chops (SE) are rubbed with a dry spice marinade that includes sesame. The menu lists sesame and dairy for the dish.', 'Sesame in a spice rub is easy to miss.', true, 'Full menu descriptions, MM-AR, October 2026, Seasonal autumn menu', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('food-allergens-lunch-dinner-0107', 'food', 'allergens-lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'The Butternut Pumpkin Salad lists sesame. Where does it come from?', null, '["The yoghurt and tahini dressing", "The toasted almonds", "The goat cheese", "The mixed leaves"]'::jsonb, '["The yoghurt and tahini dressing"]'::jsonb, 'The salad is dressed with a Greek yoghurt and tahini dressing; tahini is made from sesame. The menu lists dairy, nuts (toasted almonds) and sesame.', 'Helps you answer allergy questions about each part of the dish.', true, 'Full menu descriptions, MM-AR, October 2026, Seasonal autumn menu', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('food-allergens-lunch-dinner-0108', 'food', 'allergens-lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'A guest with a dairy allergy asks for a dessert. Which one does the menu list as free of allergens?', null, '["The ice creams", "The Dame Blanche", "The Crème Brûlée", "The sorbets: lemon, mango and raspberry"]'::jsonb, '["The sorbets: lemon, mango and raspberry"]'::jsonb, 'Our sorbets are made only with fresh fruit purée, water and sugar, so the menu lists no allergens. One scoop of each: lemon, mango and raspberry. Always tell the kitchen about the allergy.', 'A safe suggestion for guests with a dairy allergy.', true, 'Full menu descriptions, MM-AR, October 2026, Sorbets and ice creams', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('food-allergens-lunch-dinner-0109', 'food', 'allergens-lunch-dinner', 1, array['server','runner','bar','host']::text[], 'mcq', 'The Superfood Salad is vegan. Which allergen does it list?', null, '["Milk", "Gluten", "Sesame", "Nuts"]'::jsonb, '["Sesame"]'::jsonb, 'The Superfood Salad (VG, GF) lists sesame, from the toasted seeds.', 'Vegan doesn''t mean free of allergens.', true, 'Full menu descriptions, MM-AR, October 2026, Salads', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('food-allergens-breakfast-0110', 'food', 'allergens-breakfast', 1, array['server','host','runner','bar','barista']::text[], 'multi', 'Which nuts are in our homemade granola? Pick all that apply.', null, '["Walnuts", "Pecans", "Almonds", "Hazelnuts", "Pistachios"]'::jsonb, '["Walnuts", "Almonds", "Hazelnuts"]'::jsonb, 'Our homemade granola is made with oats, flour, linseed, walnuts, almonds, hazelnuts and honey. It''s in the Signature Granola, the Greek Yoghurt Crème and the Tropical Açaí Bowl.', 'Granola appears in several dishes, so a nut allergy affects all of them.', true, 'Full menu descriptions, MM-AR, October 2026, Breakfast: healthy section', 'Drafted by Claude 2026-11-05 from Full menu descriptions, MM-AR, October 2026. Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
